const counties = $input.all()[0].json;
const exportReady = counties.filter(c => 
  c.has_export_products || 
  c.international_tourism_ready
).slice(0, 5);

return exportReady.map(c => ({
  county_name: c.name,
  county_slug: c.slug,
  top_products: c.top_products || [],
  tourism_highlights: c.tourism_highlights || [],
  trade_opportunities: c.trade_opportunities || [],
  export_readiness_score: c.export_readiness_score || 50
}));

const post = $input.first().json;

// This node would:
// 1. Post to international trade portals
// 2. Send to embassy trade desks
// 3. Push to tourism board international sites
// 4. Post to social media for international audience
// 5. Send newsletter to international subscribers

return {
  ...post,
  published: true,
  channels: ['trade_portal', 'embassy_network', 'tourism_board', 'social_media', 'newsletter'],
  published_at: new Date().toISOString()
};
